CREATE TABLE department (id uuid PRIMARY KEY, code varchar(32) UNIQUE NOT NULL, name varchar(100) NOT NULL, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_user (id uuid PRIMARY KEY, username varchar(64) UNIQUE NOT NULL, school_no varchar(32) UNIQUE, display_name varchar(64) NOT NULL, password_hash varchar(255) NOT NULL, email varchar(254) NOT NULL, department_id uuid NOT NULL REFERENCES department, enabled boolean NOT NULL DEFAULT true, auth_version bigint NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role (id uuid PRIMARY KEY, code varchar(64) UNIQUE NOT NULL, name varchar(100) NOT NULL, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0);
CREATE TABLE permission (id uuid PRIMARY KEY, code varchar(100) UNIQUE NOT NULL, description varchar(255) NOT NULL);
CREATE TABLE user_role (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user, role_id uuid NOT NULL REFERENCES role, UNIQUE(user_id,role_id));
CREATE TABLE role_permission (role_id uuid NOT NULL REFERENCES role, permission_id uuid NOT NULL REFERENCES permission, PRIMARY KEY(role_id,permission_id));
CREATE TABLE campus (id uuid PRIMARY KEY, code varchar(32) UNIQUE NOT NULL, name varchar(100) NOT NULL, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0);
CREATE TABLE building (id uuid PRIMARY KEY, campus_id uuid NOT NULL REFERENCES campus, code varchar(32) UNIQUE NOT NULL, name varchar(100) NOT NULL, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0);
CREATE TABLE room (id uuid PRIMARY KEY, building_id uuid NOT NULL REFERENCES building, code varchar(32) UNIQUE NOT NULL, name varchar(100) NOT NULL, department_id uuid REFERENCES department, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0);
CREATE TABLE seat (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES room, code varchar(32) NOT NULL, has_power boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0, UNIQUE(room_id,code));
CREATE TABLE user_role_scope (id uuid PRIMARY KEY, user_role_id uuid NOT NULL REFERENCES user_role ON DELETE CASCADE, scope_type varchar(16) NOT NULL CHECK(scope_type IN ('ALL','DEPARTMENT','ROOM','SHARED')), department_id uuid REFERENCES department, room_id uuid REFERENCES room, CHECK((scope_type='DEPARTMENT' AND department_id IS NOT NULL AND room_id IS NULL) OR (scope_type='ROOM' AND room_id IS NOT NULL AND department_id IS NULL) OR (scope_type IN ('ALL','SHARED') AND room_id IS NULL AND department_id IS NULL)), UNIQUE NULLS NOT DISTINCT(user_role_id,scope_type,department_id,room_id));
CREATE TABLE opening_rule (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES room, weekday smallint NOT NULL CHECK(weekday BETWEEN 1 AND 7), start_minute int NOT NULL CHECK(start_minute BETWEEN 0 AND 1439 AND start_minute%60=0), end_minute int NOT NULL CHECK(end_minute BETWEEN 1 AND 1440 AND end_minute%60=0), CHECK(start_minute<end_minute));
CREATE TABLE system_config (key varchar(100) PRIMARY KEY, value_json jsonb NOT NULL, updated_by uuid REFERENCES app_user, version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE config_revision (id int PRIMARY KEY CHECK(id=1),version bigint NOT NULL DEFAULT 0);
INSERT INTO config_revision VALUES(1,0);
CREATE TABLE booking_guard (user_id uuid PRIMARY KEY REFERENCES app_user);
CREATE TABLE reservation (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,room_id uuid NOT NULL REFERENCES room,seat_id uuid NOT NULL REFERENCES seat,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,status varchar(32) NOT NULL CHECK(status IN ('RESERVED','CHECKED_IN','CANCELLED','NO_SHOW','COMPLETED','INTERRUPTED')),checked_in_at timestamptz,cancel_reason varchar(32),ended_at timestamptz,config_version bigint NOT NULL,max_duration_hours int NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(start_at<end_at));
CREATE INDEX reservation_user_time ON reservation(user_id,start_at,end_at) WHERE status IN ('RESERVED','CHECKED_IN');
CREATE INDEX reservation_room_time ON reservation(room_id,start_at,end_at);
CREATE TABLE violation(id uuid PRIMARY KEY,reservation_id uuid NOT NULL UNIQUE REFERENCES reservation,user_id uuid NOT NULL REFERENCES app_user,reason varchar(32) NOT NULL CHECK(reason='NO_SHOW'),occurred_at timestamptz NOT NULL);
CREATE TABLE room_application (id uuid PRIMARY KEY,applicant_id uuid NOT NULL REFERENCES app_user,applicant_department_id uuid NOT NULL REFERENCES department,room_id uuid NOT NULL REFERENCES room,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,purpose_title varchar(100) NOT NULL,purpose_description varchar(2000) NOT NULL,status varchar(32) NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED','CANCELLED','EXPIRED','COMPLETED')),current_step smallint NOT NULL CHECK(current_step IN(1,2)),expires_at timestamptz NOT NULL,cancel_reason varchar(500),config_version bigint NOT NULL,max_duration_hours int NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(start_at<end_at));
CREATE INDEX application_room_time ON room_application(room_id,start_at,end_at);
CREATE TABLE approval_step(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES room_application,step_no smallint NOT NULL CHECK(step_no IN(1,2)),required_permission varchar(100) NOT NULL,status varchar(16) NOT NULL CHECK(status IN('WAITING','PENDING','APPROVED','REJECTED')),UNIQUE(application_id,step_no));
CREATE TABLE approval_action(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES room_application,step_no smallint NOT NULL,actor_id uuid NOT NULL REFERENCES app_user,decision varchar(16) NOT NULL CHECK(decision IN('APPROVE','REJECT')),comment varchar(500),occurred_at timestamptz NOT NULL,UNIQUE(application_id,step_no));
CREATE TABLE resource_claim(id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES room,seat_id uuid REFERENCES seat,start_at timestamptz NOT NULL,end_at timestamptz,source_type varchar(2) NOT NULL CHECK(source_type IN('M1','M2','M3')),source_id uuid NOT NULL,source_version bigint NOT NULL,released_at timestamptz,created_by uuid NOT NULL,created_request_id uuid NOT NULL,release_request_id uuid,UNIQUE(source_type,source_id),CHECK((source_type='M1' AND seat_id IS NOT NULL) OR (source_type IN('M2','M3') AND seat_id IS NULL)),CHECK((source_type='M3') OR end_at IS NOT NULL),CHECK(end_at IS NULL OR start_at<end_at));
CREATE INDEX claim_room_active ON resource_claim(room_id,start_at,end_at) WHERE released_at IS NULL;
CREATE TABLE resource_source_state(source_type varchar(2) NOT NULL,source_id uuid NOT NULL,max_version bigint NOT NULL,state varchar(16) NOT NULL CHECK(state IN('ACTIVE','RELEASED')),last_command_id uuid NOT NULL,PRIMARY KEY(source_type,source_id));
CREATE TABLE processed_command(command_id uuid PRIMARY KEY,payload_hash varchar(64) NOT NULL,http_status int NOT NULL,result_json jsonb NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE room_checkin_code(id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES room,local_date date NOT NULL,code_hash varchar(255) NOT NULL,code_ciphertext text NOT NULL,expires_at timestamptz NOT NULL,UNIQUE(room_id,local_date));
CREATE TABLE notification(id uuid PRIMARY KEY,recipient_id uuid NOT NULL REFERENCES app_user,room_id uuid REFERENCES room,event_type varchar(64) NOT NULL,source_type varchar(16) NOT NULL,source_id uuid NOT NULL,dedup_key varchar(255) NOT NULL UNIQUE,payload_json jsonb NOT NULL,channel varchar(16) NOT NULL DEFAULT 'EMAIL',due_at timestamptz NOT NULL,status varchar(16) NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL,lease_owner varchar(100),lease_until timestamptz,sent_at timestamptz,read_at timestamptz,last_error_code varchar(100),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notification_delivery_due ON notification(status,next_attempt_at);
CREATE TABLE audit_event(id uuid PRIMARY KEY,actor_type varchar(16) NOT NULL,actor_id uuid NOT NULL,action varchar(100) NOT NULL,object_type varchar(64) NOT NULL,object_id uuid NOT NULL,room_id uuid,source_type varchar(16),source_id uuid,before_json jsonb,after_json jsonb,reason varchar(500),request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_object ON audit_event(object_id,created_at);
CREATE TABLE idempotency_record(id uuid PRIMARY KEY,actor_type varchar(16) NOT NULL,actor_id uuid NOT NULL,method varchar(16) NOT NULL,canonical_path varchar(255) NOT NULL,key uuid NOT NULL,request_hash varchar(64) NOT NULL,http_status int NOT NULL,response_data_json jsonb NOT NULL,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,UNIQUE(actor_type,actor_id,method,canonical_path,key));
CREATE TABLE scheduled_task(id uuid PRIMARY KEY,task_type varchar(64) NOT NULL,source_type varchar(16) NOT NULL,source_id uuid NOT NULL,dedup_key varchar(255) NOT NULL UNIQUE,due_at timestamptz NOT NULL,status varchar(16) NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL,lease_owner varchar(100),lease_until timestamptz,last_error_code varchar(100));
CREATE INDEX scheduled_task_due ON scheduled_task(status,next_attempt_at);
CREATE TABLE rate_limit_bucket(bucket_key varchar(200) PRIMARY KEY,recent_attempts jsonb NOT NULL DEFAULT '[]',blocked_until timestamptz,version bigint NOT NULL DEFAULT 0);
